// FUNCTION: BFME2 0x0037B146 size=70 name=?rva0037B146@Rva0037B146@@QAEXXZ evidence=?:placeholder tier=B hypothesis:Z
void RecorderClass::cullBadCommands()
{
	if (m_doingAnalysis)
		return;

	GameMessage *msg = TheCommandList->getFirstMessage();
	GameMessage *next = NULL;
	while (msg != NULL)
	{
		next = msg->next();
		if (msg->getType() > GameMessage::MSG_BEGIN_NETWORK_MESSAGES && msg->getType() < GameMessage::MSG_END_NETWORK_MESSAGES && msg->getType() != GameMessage::MSG_LOGIC_CRC)
		{
			::delete msg;
		}
		msg = next;
	}
}

