bool RecorderClass::isMultiplayer()
{
	if (m_mode == RECORDERMODETYPE_PLAYBACK) {
		for (int i = 0; i < MAX_SLOTS; i++) {
			GameSlot *slot = m_gameInfo.getSlot(i);
			if (slot && slot->isOccupied())
				return true;
		}
	}
	GameLogic *logic = TheGameLogic;
	int mode = logic->getGameMode();
	if (mode == 0 || mode == 6 || logic->rva00085124())
		return false;
	if (logic->m_unk0x114 != 3)
		return true;
	if (TheNetwork || TheSkirmishGameInfo)
		return true;
	return false;
}

